files.content:
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background: #1a1c2c;
  color: #f4f4f4;
  font-family: 'Courier New', Courier, monospace;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  image-rendering: pixelated;
}
.quiz {
  background: #333c57;
  border: 4px solid #111;
  box-shadow: 8px 8px 0 #111;
  padding: 20px;
  width: min(90%, 420px);
  text-align: center;
}
h1 {
  font-size: 1.8rem;
  margin-bottom: 20px;
  text-shadow: 3px 3px 0 #111;
}
.question {
  font-size: 1.5rem;
  margin-bottom: 20px;
  padding: 12px;
  background: #212838;
  border: 2px solid #111;
}
.answers, .controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 20px;
}
.answer-btn, .control-btn {
  font-family: inherit;
  font-size: 1.2rem;
  padding: 10px 20px;
  background: #efefef;
  color: #111;
  border: 3px solid #111;
  box-shadow: 4px 4px 0 #111;
  cursor: pointer;
  text-transform: uppercase;
}
.answer-btn:disabled, .control-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
.answer-btn:focus-visible, .control-btn:focus-visible {
  outline: 3px solid #ffcc00;
  outline-offset: 2px;
}
.score-line {
  font-size: 1.3rem;
  margin-bottom: 20px;
}
button:active:not(:disabled) {
  box-shadow: 1px 1px 0 #111;
  transform: translate(3px, 3px);
}

(function() {
  'use strict';

  const questionEl = document.getElementById('question');
  const answerA = document.getElementById('answer-a');
  const answerB = document.getElementById('answer-b');
  const scoreEl = document.getElementById('score');
  const nextBtn = document.getElementById('next');
  const restartBtn = document.getElementById('restart');

  const questions = [
    { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  ];

  let currentIndex = 0;
  let score = 0;
  let answered = false;

  function updateQuestion() {
    const q = questions[currentIndex];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    answered = false;
    answerA.disabled = false;
    answerB.disabled = false;
  }

  function lockAnswers() {
    answered = true;
    answerA.disabled = true;
    answerB.disabled = true;
  }

  function handleAnswer(e) {
    if (answered) return;
    const id = e.target.id;
    const q = questions[currentIndex];
    lockAnswers();
    if (id === q.correct) {
      score += 1;
      scoreEl.textContent = score;
    }
  }

  function handleNext() {
    if (currentIndex === 0) {
      currentIndex = 1;
      updateQuestion();
    } else if (currentIndex === 1) {
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
      nextBtn.disabled = true;
    }
  }

  function handleRestart() {
    currentIndex = 0;
    score = 0;
    scoreEl.textContent = score;
    updateQuestion();
    nextBtn.disabled = false;
  }

  answerA.addEventListener('click', handleAnswer);
  answerB.addEventListener('click', handleAnswer);
  nextBtn.addEventListener('click', handleNext);
  restartBtn.addEventListener('click', handleRestart);

  handleRestart();
})();
